import asyncio
import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

async def async_func():
    return "async_func"

def sync_func():
    return "sync_func"

def sync_wrapper(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def async_wrapper(func):
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapper

# Case 1: sync_func wrapped by sync_wrapper
wrapped_sync_sync = sync_wrapper(sync_func)

# Case 2: async_func wrapped by sync_wrapper
wrapped_async_sync = sync_wrapper(async_func)

# Case 3: sync_func wrapped by async_wrapper
wrapped_sync_async = async_wrapper(sync_func)

# Case 4: async_func wrapped by async_wrapper
wrapped_async_async = async_wrapper(async_func)

# Case 5: partial of sync_func
partial_sync = functools.partial(sync_func)

# Case 6: partial of async_func
partial_async = functools.partial(async_func)

@app.get("/sync_sync")
def test_sync_sync(dep=Depends(wrapped_sync_sync)):
    return dep

@app.get("/async_sync")
def test_async_sync(dep=Depends(wrapped_async_sync)):
    return dep

@app.get("/sync_async")
def test_sync_async(dep=Depends(wrapped_sync_async)):
    return dep

@app.get("/async_async")
def test_async_async(dep=Depends(wrapped_async_async)):
    return dep

@app.get("/partial_sync")
def test_partial_sync(dep=Depends(partial_sync)):
    return dep

@app.get("/partial_async")
def test_partial_async(dep=Depends(partial_async)):
    return dep

client = TestClient(app)

def test_all():
    print("Testing sync_sync...")
    assert client.get("/sync_sync").json() == "sync_func"
    print("Testing async_sync...")
